package thebetweenlands.api.aspect;

import java.math.RoundingMode;
import java.text.DecimalFormat;

import net.minecraft.nbt.NBTTagCompound;
import thebetweenlands.common.registries.AspectRegistry;

public final class Aspect implements Comparable<Aspect> {
	public static final DecimalFormat ASPECT_AMOUNT_FORMAT = new DecimalFormat("#.##");

	static {
		ASPECT_AMOUNT_FORMAT.setRoundingMode(RoundingMode.CEILING);
	}

	/**
	 * The type of this aspect
	 */
	public final IAspectType type;

	/**
	 * The amount of this aspect
	 */
	public final int amount;

	public Aspect(IAspectType aspect, int amount) {
		if(aspect == null) throw new RuntimeException("Aspect can't be null");
		this.type = aspect;
		this.amount = amount;
	}

	public float getDisplayAmount() {
		return this.amount / 1000.0F;
	}

	public String getRoundedDisplayAmount() {
		return ASPECT_AMOUNT_FORMAT.format(this.getDisplayAmount());
	}

	public NBTTagCompound writeToNBT(NBTTagCompound nbt) {
		nbt.setString("aspect", this.type.getName());
		nbt.setInteger("amount", this.amount);
		return nbt;
	}

	public static Aspect readFromNBT(NBTTagCompound nbt) {
		String aspectName = nbt.getString("aspect");
		int amount = nbt.getInteger("amount");
		IAspectType aspectType = AspectRegistry.getAspectTypeFromName(aspectName);
		if(aspectType != null) {
			return new Aspect(aspectType, amount);
		}
		return null;
	}

	@Override
	public int hashCode() {
		final int prime = 31;
		int result = 1;
		result = prime * result + Float.floatToIntBits(this.amount);
		result = prime * result + ((this.type == null) ? 0 : this.type.hashCode());
		return result;
	}

	@Override
	public boolean equals(Object obj) {
		if (this == obj)
			return true;
		if (obj == null)
			return false;
		if (getClass() != obj.getClass())
			return false;
		Aspect other = (Aspect) obj;
		if (Float.floatToIntBits(this.amount) != Float.floatToIntBits(other.amount))
			return false;
		if (this.type == null) {
			if (other.type != null)
				return false;
		} else if (!this.type.equals(other.type))
			return false;
		return true;
	}

	@Override
	public int compareTo(Aspect other) {
		return this.type.getName().compareTo(other.type.getName());
	}
}

package thebetweenlands.api.aspect;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Map.Entry;
import java.util.Set;

import javax.annotation.Nonnull;

import com.google.common.collect.ImmutableList;
import com.google.common.collect.ImmutableSet;

import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.nbt.NBTTagList;
import net.minecraftforge.common.util.Constants;
import thebetweenlands.common.registries.AspectRegistry;

/**
 * The aspect container contains dynamic and static aspects.
 * Static aspects are only saved when their amount changes, so that they
 * can be updated in case the aspect distribution seed is changed. Once
 * the amount of a static aspect in this container has changed it is no 
 * longer treated as a static aspect.
 */
public class AspectContainer {
	protected static final class Storage {
		private final IAspectType type;
		private final AspectContainer container;
		private int dynamicAmount;
		private int storedStaticAmount;
		private boolean hasStoredStaticAmount;

		private Storage(IAspectType type, AspectContainer container) {
			this.type = type;
			this.dynamicAmount = 0;
			this.storedStaticAmount = 0;
			this.hasStoredStaticAmount = false;
			this.container = container;
		}

		/**
		 * Writes the storage data to the specified NBT
		 * @param nbt
		 * @return
		 */
		public NBTTagCompound writeToNBT(NBTTagCompound nbt) {
			nbt.setInteger("dynamic", this.dynamicAmount);
			nbt.setInteger("storedStatic", this.storedStaticAmount);
			nbt.setBoolean("hasStoredStatic", this.hasStoredStaticAmount);
			return nbt;
		}

		/**
		 * Reads the storage data from the specified NBT
		 * @param nbt
		 * @return
		 */
		public Storage readFromNBT(NBTTagCompound nbt) {
			this.dynamicAmount = nbt.getInteger("dynamic");
			this.storedStaticAmount = nbt.getInteger("storedStatic");
			this.hasStoredStaticAmount = nbt.getBoolean("hasStoredStatic");
			return this;
		}

		/**
		 * Returns the amount
		 * @param dynamic
		 * @param staticAspects
		 * @return
		 */
		public int getAmount(boolean dynamic) {
			if(dynamic) {
				return this.dynamicAmount;
			} else {
				if(this.hasStoredStaticAmount) {
					//Return stored static amount if it has been changed previously
					return this.storedStaticAmount;
				} else {
					List<Aspect> staticAspects = this.container.getStaticAspects();
					if(staticAspects != null) {
						int amount = 0;
						for(Aspect aspect : staticAspects) {
							if(aspect.type == this.type) {
								amount += aspect.amount;
							}
						}
						return amount;
					} else {
						return 0;
					}
				}
			}
		}

		/**
		 * Sets the amount
		 * @param dynamic
		 * @param amount
		 * @return
		 */
		public Storage setAmount(boolean dynamic, int amount) {
			if(dynamic) {
				this.dynamicAmount = amount;
			} else {
				this.storedStaticAmount = amount;
				this.hasStoredStaticAmount = true;
			}
			return this;
		}

		/**
		 * Resets the static amount to the default
		 * @return
		 */
		public Storage resetStaticAmount() {
			this.storedStaticAmount = 0;
			this.hasStoredStaticAmount = false;
			return this;
		}
	}

	private final Map<IAspectType, Storage> storage = new HashMap<IAspectType, Storage>();

	/**
	 * Returns the storage for the specified aspect
	 * @param type
	 * @return
	 */
	protected final Storage getStorage(IAspectType type) {
		Storage storage = this.storage.get(type);
		if(storage == null) {
			this.storage.put(type, storage = new Storage(type, this));
		}
		return storage;
	}

	public AspectContainer() {
		for(IAspectType type : AspectRegistry.ASPECT_TYPES) {
			this.storage.put(type, new Storage(type, this));
		}
	}

	/**
	 * Called when the data was changed
	 */
	protected void onChanged() { }

	/**
	 * Returns the set of all stored aspect types
	 * @return
	 */
	protected final ImmutableSet<IAspectType> getStoredAspectTypes() {
		return ImmutableSet.copyOf(this.storage.keySet());
	}

	/**
	 * Returns the amount of the specified aspect type
	 * @param type
	 * @return
	 */
	protected final int get(IAspectType type, boolean dynamic) {
		return this.getStorage(type).getAmount(dynamic);
	}

	/**
	 * Returns the amount of the specified aspect type
	 * @param type
	 * @return
	 */
	public final int get(IAspectType type) {
		Storage storage = this.getStorage(type);
		return storage.getAmount(true) + storage.getAmount(false);
	}

	/**
	 * Returns the {@link Aspect} object with the specified aspect type
	 * @param type
	 * @return
	 */
	public final Aspect getAspect(IAspectType type)  {
		return new Aspect(type, this.get(type));
	}

	/**
	 * Sets the amount of the specified aspect type
	 * @param type
	 * @param amount
	 * @return
	 */
	public final AspectContainer set(IAspectType type, int amount) {
		if(amount >= 0) {
			Storage storage = this.getStorage(type);
			int diff = this.get(type) - amount;
			if(diff > 0) {
				//Remove
				int dynAmounts = storage.getAmount(true);
				storage.setAmount(true, Math.max(dynAmounts - diff, 0));
				diff = Math.max(diff - dynAmounts, 0);
				if(diff > 0) {
					//Drain static aspect last and only if necessary
					storage.setAmount(false, storage.getAmount(false) - diff);
				}
				this.onChanged();
			} else if(diff < 0) {
				//Add
				storage.setAmount(true, amount - storage.getAmount(false));
				this.onChanged();
			}
		}
		return this;
	}

	/**
	 * Adds the amount of the specified aspect type
	 * @param type
	 * @param amount
	 * @return
	 */
	public final AspectContainer add(IAspectType type, int amount) {
		Storage storage = this.getStorage(type);

		storage.dynamicAmount += amount;

		if(amount != 0) {
			this.onChanged();
		}

		return this;
	}

	/**
	 * Drains an amount from the specified aspect type
	 * @param type
	 * @param desiredAmount
	 * @return the drained amount
	 */
	public final int drain(IAspectType type, int desiredAmount) {
		int amount = this.get(type);
		if(desiredAmount >= amount) {
			this.set(type, 0);
			return amount;
		}
		this.set(type, amount - desiredAmount);
		return desiredAmount;
	}

	/**
	 * Returns whether this container is empty
	 * @return
	 */
	public final boolean isEmpty() {
		for(Storage storage : this.storage.values()) {
			if(storage.getAmount(true) + storage.getAmount(false) > 0)
				return false;
		}
		return true;
	}

	/**
	 * Writes this container to the specified NBT
	 * @param nbt
	 * @return
	 */
	public NBTTagCompound save(NBTTagCompound nbt) {
		NBTTagList typesList = new NBTTagList();
		for(Entry<IAspectType, Storage> entry : this.storage.entrySet()) {
			IAspectType type = entry.getKey();
			Storage storage = entry.getValue();

			if(storage.dynamicAmount == 0 && !storage.hasStoredStaticAmount) {
				//Doesn't have to be saved
				continue;
			}

			NBTTagCompound storageNbt = new NBTTagCompound();
			storageNbt.setTag("aspect", type.writeToNBT(new NBTTagCompound()));
			storageNbt.setTag("storage", storage.writeToNBT(new NBTTagCompound()));

			typesList.appendTag(storageNbt);
		}
		nbt.setTag("container", typesList);
		return nbt;
	}

	/**
	 * Reads the container from the specified NBT and adds the static aspects
	 * @param nbt
	 * @param staticAspects
	 * @return
	 */
	public AspectContainer read(NBTTagCompound nbt) {
		NBTTagList typesList = nbt.getTagList("container", Constants.NBT.TAG_COMPOUND);
		for(int i = 0; i < typesList.tagCount(); i++) {
			NBTTagCompound storageNbt = typesList.getCompoundTagAt(i);
			IAspectType type = IAspectType.readFromNBT(storageNbt.getCompoundTag("aspect"));
			if(type == null)
				continue;
			Storage storage = this.getStorage(type);
			storage.readFromNBT(storageNbt.getCompoundTag("storage"));
		}
		return this;
	}

	/**
	 * Returns a list of static aspects of this container
	 * @return
	 */
	@Nonnull
	protected List<Aspect> getStaticAspects() {
		return ImmutableList.of();
	}

	/**
	 * Returns a list of all aspects in this container
	 * @return
	 */
	@Nonnull
	public List<Aspect> getAspects() {
		List<Aspect> aspects = new ArrayList<Aspect>();
		Set<IAspectType> types = this.getStoredAspectTypes();
		for(IAspectType type : types) {
			int amount = this.get(type);
			if(amount > 0)
				aspects.add(new Aspect(type, amount));
		}
		return aspects;
	}
}

package thebetweenlands.api.aspect;

import net.minecraft.item.ItemStack;
import thebetweenlands.common.herblore.aspect.AspectManager;
import thebetweenlands.common.herblore.aspect.IItemStackMatcher;

/**
 * Used as an identifier for items that carry aspects.
 * Instances can be obtained from {@link AspectManager#getAspectItem(ItemStack)}
 */
public class AspectItem {
	private final ItemStack original;
	private final IItemStackMatcher matcher;

	/**
	 * Creates a new aspect item
	 * @param stack
	 * @param matcher
	 */
	public AspectItem(ItemStack stack, IItemStackMatcher matcher) {
		this.original = stack;
		this.matcher = matcher;
	}

	/**
	 * Returns a copy of the original item stack
	 * @return
	 */
	public ItemStack getOriginal() {
		return this.original.copy();
	}

	/**
	 * Returns the item stack matcher
	 * @return
	 */
	public IItemStackMatcher getMatcher() {
		return this.matcher;
	}

	/**
	 * Returns whether the specified item matches
	 * @param stack
	 * @return
	 */
	public boolean matches(ItemStack stack) {
		return this.matcher.matches(this.original, stack);
	}
}

package thebetweenlands.api.aspect;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.Map.Entry;

import net.minecraft.entity.player.EntityPlayer;
import net.minecraft.entity.player.InventoryPlayer;
import net.minecraft.item.ItemStack;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.nbt.NBTTagList;
import net.minecraftforge.common.util.Constants;
import thebetweenlands.api.aspect.DiscoveryContainer.AspectDiscovery.EnumDiscoveryResult;
import thebetweenlands.api.item.IDiscoveryProvider;
import thebetweenlands.common.herblore.aspect.AspectManager;

public class DiscoveryContainer<T> {
	private final Map<AspectItem, List<IAspectType>> discoveredStaticAspects = new HashMap<AspectItem, List<IAspectType>>();
	private final IDiscoveryProvider<T> provider;
	private final T providerObj;

	public DiscoveryContainer(IDiscoveryProvider<T> provider, T providerObj) {
		this.provider = provider;
		this.providerObj = providerObj;
	}

	private DiscoveryContainer() {
		this.provider = null;
		this.providerObj = null;
	}

	/**
	 * Returns a new empty discovery container
	 * @return
	 */
	@SuppressWarnings("rawtypes")
	public static DiscoveryContainer<?> empty() {
		return new DiscoveryContainer();
	}

	/**
	 * Reads a discovery container from an NBT
	 *
	 * @param nbt
	 * @return
	 */
	public static DiscoveryContainer<?> readFromNBT(NBTTagCompound nbt) {
		DiscoveryContainer<?> container = empty();
		container.updateFromNBT(nbt, false);
		return container;
	}

	/**
	 * Returns how many aspects of the specified item are already discovered
	 * @param item
	 * @return
	 */
	private int getDiscoveryCount(AspectItem item) {
		return !this.discoveredStaticAspects.containsKey(item) ? 0 : this.discoveredStaticAspects.get(item).size();
	}

	private DiscoveryContainer<T> saveContainer() {
		if(this.provider != null && this.providerObj != null)
			this.provider.saveContainer(this.providerObj, this);
		return this;
	}

	/**
	 * Discovers a new aspect of an item and returns the discovery result
	 * @param manager
	 * @param aspectItem
	 * @return
	 */
	public AspectDiscovery discover(AspectManager manager, AspectItem aspectItem) {
		List<Aspect> staticAspects = manager.getStaticAspects(aspectItem);
		if(staticAspects.isEmpty()) {
			return new AspectDiscovery(EnumDiscoveryResult.NONE, null, false);
		}
		int discoveryCount = this.getDiscoveryCount(aspectItem) + 1;
		if(discoveryCount > staticAspects.size()) {
			return new AspectDiscovery(EnumDiscoveryResult.END, null, false);
		}
		Aspect undiscovered = this.getUndiscoveredAspect(staticAspects, this.discoveredStaticAspects.get(aspectItem));
		this.addDiscovery(aspectItem, undiscovered.type);
		if(discoveryCount == staticAspects.size()) {
			this.saveContainer();
			return new AspectDiscovery(EnumDiscoveryResult.LAST, undiscovered, true);
		} else {
			this.saveContainer();
			return new AspectDiscovery(EnumDiscoveryResult.NEW, undiscovered, true);
		}
	}

	public boolean haveDiscoveredAll(AspectManager manager) {
		for(Entry<AspectItem, List<Aspect>> e : manager.getMatchedAspects().entrySet()) {
			List<Aspect> staticAspects = manager.getStaticAspects(e.getKey());
			if (getDiscoveryCount(e.getKey()) < staticAspects.size())
				return false;
		}
		return true;
	}

	/**
	 * Discovers all aspects of all aspect items
	 * @param manager
	 */
	public void discoverAll(AspectManager manager) {
		for(Entry<AspectItem, List<Aspect>> e : manager.getMatchedAspects().entrySet()) {
			for(Aspect a : e.getValue())
				this.addDiscovery(e.getKey(), a.type);
		}
		this.saveContainer();
	}

	/**
	 * Removes all discoveries of the specified item
	 * @param item
	 */
	public void resetDiscovery(AspectItem item) {
		this.discoveredStaticAspects.remove(item);
		this.saveContainer();
	}

	/**
	 * Resets all aspect discoveries of all aspect items
	 */
	public void resetAllDiscovery() {
		this.discoveredStaticAspects.clear();
		this.saveContainer();
	}

	/**
	 * Adds a single aspect discovery
	 * @param item
	 * @param discovered
	 */
	public void addDiscovery(AspectItem item, IAspectType discovered) {
		List<IAspectType> discoveredAspects = this.discoveredStaticAspects.get(item);
		if(discoveredAspects == null) {
			this.discoveredStaticAspects.put(item, discoveredAspects = new ArrayList<IAspectType>());
		}
		if(!discoveredAspects.contains(discovered))
			discoveredAspects.add(discovered);
		this.saveContainer();
	}

	private Aspect getUndiscoveredAspect(List<Aspect> all, List<IAspectType> discovered) {
		if(discovered == null) {
			return all.size() == 0 ? null : all.get(0);
		}
		for(Aspect a : all) {
			if(!discovered.contains(a.type))
				return a;
		}
		return null;
	}

	/**
	 * Writes this discovery container to an NBT
	 * @param nbt
	 */
	public NBTTagCompound writeToNBT(NBTTagCompound nbt) {
		NBTTagList discoveryList = new NBTTagList();
		Iterator<Entry<AspectItem, List<IAspectType>>> discoveryIT = this.discoveredStaticAspects.entrySet().iterator();
		while(discoveryIT.hasNext()) {
			Entry<AspectItem, List<IAspectType>> e = discoveryIT.next();
			if(e.getKey() == null || e.getValue() == null || e.getValue().size() == 0) {
				discoveryIT.remove();
				continue;
			}
			NBTTagCompound discoveryEntry = new NBTTagCompound();
			AspectManager.writeAspectItemToNbt(e.getKey(), discoveryEntry);
			NBTTagList aspectListCompound = new NBTTagList();
			for(IAspectType type : e.getValue()) {
				aspectListCompound.appendTag(type.writeToNBT(new NBTTagCompound()));
			}
			discoveryEntry.setTag("aspects", aspectListCompound);
			discoveryList.appendTag(discoveryEntry);
		}
		nbt.setTag("discoveries", discoveryList);
		return nbt;
	}

	/**
	 * Updates this discovery container from an NBT
	 * @param nbt
	 * @return
	 */
	public DiscoveryContainer<T> updateFromNBT(NBTTagCompound nbt, boolean save) {
		this.discoveredStaticAspects.clear();
		NBTTagList discoveryList = nbt.getTagList("discoveries", Constants.NBT.TAG_COMPOUND);
		int discoveryEntries = discoveryList.tagCount();
		for (int i = 0; i < discoveryEntries; i++) {
			NBTTagCompound discoveryEntry = discoveryList.getCompoundTagAt(i);
			AspectItem item = AspectManager.readAspectItemFromNBT(discoveryEntry);
			List<IAspectType> aspectTypeList = new ArrayList<IAspectType>();
			NBTTagList aspectListCompound = discoveryEntry.getTagList("aspects", Constants.NBT.TAG_COMPOUND);
			for (int c = 0; c < aspectListCompound.tagCount(); c++) {
				NBTTagCompound aspectTypeCompound = aspectListCompound.getCompoundTagAt(c);
				aspectTypeList.add(IAspectType.readFromNBT(aspectTypeCompound));
			}
			this.discoveredStaticAspects.put(item, aspectTypeList);
		}
		if (save)
			this.saveContainer();
		return this;
	}

	/**
	 * Merges the discoveries of another container into this container
	 * @param other
	 * @return
	 */
	public DiscoveryContainer<T> mergeDiscoveries(DiscoveryContainer<?> other) {
		boolean changed = false;
		for (Entry<AspectItem, List<IAspectType>> entry : other.discoveredStaticAspects.entrySet()) {
			AspectItem otherItem = entry.getKey();
			List<IAspectType> otherTypes = entry.getValue();
			if (!this.discoveredStaticAspects.containsKey(otherItem)) {
				this.discoveredStaticAspects.put(otherItem, otherTypes);
				changed = true;
			} else {
				List<IAspectType> aspectTypes = this.discoveredStaticAspects.get(otherItem);
				for (IAspectType otherType : otherTypes) {
					if (!aspectTypes.contains(otherType)) {
						aspectTypes.add(otherType);
						changed = true;
					}
				}
			}
		}
		if(changed)
			this.saveContainer();
		return this;
	}

	/**
	 * Returns the list of all the discovered aspects of the specified item.
	 * @param manager
	 * @param item
	 * @return
	 */
	public List<Aspect> getDiscoveredStaticAspects(AspectManager manager, AspectItem item) {
		List<Aspect> discoveredStaticAspects = new ArrayList<Aspect>();
		if(this.discoveredStaticAspects.containsKey(item)) {
			List<IAspectType> discoveredAspects = this.discoveredStaticAspects.get(item);
			List<Aspect> staticAspects = manager.getStaticAspects(item);
			for(Aspect a : staticAspects) {
				if(discoveredAspects.contains(a.type))
					discoveredStaticAspects.add(a);
			}
		}
		return discoveredStaticAspects;
	}

	public static class AspectDiscovery {
		public final EnumDiscoveryResult result;
		public final boolean successful;
		public final Aspect discovered;

		private AspectDiscovery(EnumDiscoveryResult result, Aspect discovered, boolean successful) {
			this.result = result;
			this.discovered = discovered;
			this.successful = successful;
		}

		public static enum EnumDiscoveryResult {
			NONE, NEW, LAST, END
		}
	}

	/**
	 * Returns whether a player has a discovery provider to write to
	 * @param player
	 * @return
	 */
	public static boolean hasDiscoveryProvider(EntityPlayer player) {
		InventoryPlayer inventory = player.inventory;
		for(int i = 0; i < inventory.getSizeInventory(); i++) {
			ItemStack stack = inventory.getStackInSlot(i);
			if(!stack.isEmpty() && stack.getItem() instanceof IDiscoveryProvider)
				return true;
		}
		return false;
	}

	/**
	 * Returns a list of all writable discovery containers in the inventory of a player
	 * @param player
	 * @return
	 */
	public static List<DiscoveryContainer<?>> getWritableDiscoveryContainers(EntityPlayer player) {
		List<DiscoveryContainer<?>> containerList = new ArrayList<DiscoveryContainer<?>>();
		InventoryPlayer inventory = player.inventory;
		for(int i = 0; i < inventory.getSizeInventory(); i++) {
			ItemStack stack = inventory.getStackInSlot(i);
			if(!stack.isEmpty() && stack.getItem() instanceof IDiscoveryProvider) {
				@SuppressWarnings("unchecked")
				IDiscoveryProvider<ItemStack> provider = (IDiscoveryProvider<ItemStack>) stack.getItem();
				DiscoveryContainer<?> container = provider.getContainer(stack);
				if(container != null)
					containerList.add(container);
			}
		}
		return containerList;
	}

	/**
	 * Merges all discovery containers in the inventory of a player into one discovery container.
	 * Mostly used to get the combined knowledge of the player.
	 * @param player
	 * @return
	 */
	public static DiscoveryContainer<?> getMergedDiscoveryContainer(EntityPlayer player) {
		List<DiscoveryContainer<?>> containerList = getWritableDiscoveryContainers(player);
		DiscoveryContainer<?> merged = DiscoveryContainer.empty();
		for(DiscoveryContainer<?> container : containerList) {
			if(container != null)
				merged.mergeDiscoveries(container);
		}
		return merged;
	}

	/**
	 * Adds a discovered aspect to all discovery containers of the player
	 * @param player
	 * @param item
	 * @param type
	 */
	public static void addDiscoveryToContainers(EntityPlayer player, AspectItem item, IAspectType type) {
		List<DiscoveryContainer<?>> discoveryContainers = getWritableDiscoveryContainers(player);
		for(DiscoveryContainer<?> container : discoveryContainers)
			container.addDiscovery(item, type);
	}
}

