		logger = event.getModLog();

		//Configuration File
		ConfigHelper.init();

		BetweenlandsAPI.init();

		dimensionType = DimensionType.register(DIMENSION_NAME, "_betweenlands", BetweenlandsConfig.WORLD_AND_DIMENSION.dimensionId, WorldProviderBetweenlands.class, false);
