import thebetweenlands.common.registries.FluidRegistry;
import thebetweenlands.common.registries.SoundRegistry;

public class TileEntityPurifier extends TileEntityBasicInventory implements IFluidHandler, ITickable {
    private static final int MAX_TIME = 432;
    public final FluidTank waterTank;
    private final IFluidTankProperties[] properties = new IFluidTankProperties[1];
    public int time = 0;
    public boolean lightOn = false;
    private int prevStackSize = 0;
    private Item prevItem;
    private boolean isPurifyingClient = false;

    public TileEntityPurifier() {
        super(3, "container.bl.purifier");
        this.waterTank = new FluidTank(FluidRegistry.SWAMP_WATER, 0, Fluid.BUCKET_VOLUME * 4);
        this.waterTank.setTileEntity(this);
        this.properties[0] = new FluidTankPropertiesWrapper(this.waterTank);
    }

    @Override
    public void readFromNBT(NBTTagCompound nbt) {
        super.readFromNBT(nbt);
        waterTank.readFromNBT(nbt.getCompoundTag("waterTank"));
        lightOn = nbt.getBoolean("state");
        time = nbt.getInteger("progress");
    }

    @Override
    public NBTTagCompound writeToNBT(NBTTagCompound nbt) {
        nbt = super.writeToNBT(nbt);
        nbt.setTag("waterTank", waterTank.writeToNBT(new NBTTagCompound()));
        nbt.setBoolean("state", lightOn);
        nbt.setInteger("progress", time);
        return nbt;
    }

    @Override
    public SPacketUpdateTileEntity getUpdatePacket() {
        NBTTagCompound nbt = new NBTTagCompound();
        this.writePacketNbt(nbt);
        return new SPacketUpdateTileEntity(pos, 0, nbt);
    }

    @Override
    public void onDataPacket(NetworkManager net, SPacketUpdateTileEntity packet) {
        this.readPacketNbt(packet.getNbtCompound());
    }

    protected NBTTagCompound writePacketNbt(NBTTagCompound nbt) {
        nbt.setBoolean("state", lightOn);
        nbt.setTag("waterTank", waterTank.writeToNBT(new NBTTagCompound()));
        nbt.setBoolean("isPurifying", this.isPurifying());
        this.writeInventoryNBT(nbt);
        return nbt;
    }

    protected void readPacketNbt(NBTTagCompound nbt) {
        NBTTagCompound compound = nbt;
        lightOn = compound.getBoolean("state");
        waterTank.readFromNBT(compound.getCompoundTag("waterTank"));
        this.readInventoryNBT(nbt);
        isPurifyingClient = compound.getBoolean("isPurifying");
    }

    @Override
    public NBTTagCompound getUpdateTag() {
        NBTTagCompound nbt = super.getUpdateTag();
        this.writePacketNbt(nbt);
        return nbt;
    }

    @Override
    public void handleUpdateTag(NBTTagCompound nbt) {
        super.handleUpdateTag(nbt);
        this.readPacketNbt(nbt);
    }

    public int getPurifyingProgress() {
        return time / 36;
    }

    public boolean isPurifying() {
        return time > 0 || this.isPurifyingClient;
    }

    public int getWaterAmount() {
        return waterTank.getFluidAmount();
    }

    public int getTanksFullValue() {
        return waterTank.getCapacity();
    }

    public int getScaledWaterAmount(int scale) {
        return waterTank.getFluid() != null ? (int) ((float) waterTank.getFluid().amount / (float) waterTank.getCapacity() * scale) : 0;
    }

    public void getGUIData(int id, int value) {
        switch (id) {
            case 0:
                time = value;
                break;
            case 1:
                if (waterTank.getFluid() == null)
                    waterTank.setFluid(new FluidStack(FluidRegistry.SWAMP_WATER, value));
                else
                    waterTank.getFluid().amount = value;
                break;
        }
    }

    public void sendGUIData(ContainerPurifier purifier, IContainerListener craft) {
        craft.sendWindowProperty(purifier, 0, time);
        craft.sendWindowProperty(purifier, 1, waterTank.getFluid() != null ? waterTank.getFluid().amount : 0);
    }

    @Override
    public void update() {
        if (world.isRemote)
            return;
        ItemStack output = PurifierRecipe.getRecipeOutput(inventory.get(1));
        if (hasFuel() && !outputIsFull()) {
            if (!output.isEmpty() && getWaterAmount() > 0 && inventory.get(2).isEmpty() || !output.isEmpty() && getWaterAmount() > 0 && !inventory.get(2).isEmpty() && inventory.get(2).isItemEqual(output)) {
                time++;
                if (time % 108 == 0)
                    world.playSound(null, pos.getX(), pos.getY(), pos.getZ(), SoundRegistry.PURIFIER, SoundCategory.BLOCKS, 1.5F, 1.0F);
                if (!lightOn)
                    setIlluminated(true);
                if (time >= MAX_TIME) {
                    for (int i = 0; i < 2; i++)
                        if (!inventory.get(i).isEmpty())
                            if (inventory.get(i).getCount() - 1 <= 0)
                                inventory.set(i, ItemStack.EMPTY);
                            else
                                inventory.get(i).shrink(1);
                    extractFluids(new FluidStack(FluidRegistry.SWAMP_WATER, Fluid.BUCKET_VOLUME / 4));
                    if (inventory.get(2).isEmpty()) {
                        inventory.set(2, output.copy());
                    } else if (inventory.get(2).isItemEqual(output)) {
                        inventory.get(2).grow(output.getCount());
                    }
                    time = 0;
                    markDirty();
                    boolean canRun = !output.isEmpty() && getWaterAmount() > 0 && inventory.get(2).isEmpty() || !output.isEmpty() && getWaterAmount() > 0 && !inventory.get(2).isEmpty() && inventory.get(2).isItemEqual(output);
                    if (!canRun) setIlluminated(false);
                }
            }
        }
        if (time > 0) {
            markDirty();
        }
        if (getStackInSlot(0).isEmpty() || getStackInSlot(1).isEmpty() || outputIsFull()) {
            time = 0;
            markDirty();
            setIlluminated(false);
        }
        if (this.prevStackSize != (!inventory.get(2).isEmpty() ? inventory.get(2).getCount() : 0)) {
            markDirty();
        }
        if (this.prevItem != (!inventory.get(2).isEmpty() ? inventory.get(2).getItem() : null)) {
            markDirty();
        }
        this.prevItem = !inventory.get(2).isEmpty() ? inventory.get(2).getItem() : null;
        this.prevStackSize = !inventory.get(2).isEmpty() ? inventory.get(2).getCount() : 0;
    }

    private void extractFluids(FluidStack fluid) {
        if (fluid.isFluidEqual(waterTank.getFluid()))
            waterTank.drain(fluid.amount, true);
        markDirty();
    }

    public boolean hasFuel() {
        return !getStackInSlot(0).isEmpty() && EnumItemMisc.SULFUR.isItemOf(getStackInSlot(0)) && getStackInSlot(0).getCount() >= 1;
    }

    private boolean outputIsFull() {
        return !getStackInSlot(2).isEmpty() && (getStackInSlot(2).getCount() >= getInventoryStackLimit() || getStackInSlot(2).getCount() >= getStackInSlot(2).getMaxStackSize());
    }

    public void setIlluminated(boolean state) {
        lightOn = state;
        world.addBlockEvent(pos, getBlockType(), 0, lightOn ? 1 : 0);
    }

    @Override
    public boolean receiveClientEvent(int eventId, int eventData) {
        switch (eventId) {
            case 0:
                lightOn = eventData == 1;
                world.checkLight(pos);
                return true;
            default:
                return false;
        }
    }

    @Override
    public int[] getSlotsForFace(EnumFacing facing) {
        if (facing == EnumFacing.DOWN)
            return new int[]{2};
        if (facing == EnumFacing.UP)
            return new int[]{1};
        return new int[]{0};
    }

    @Override
    public IFluidTankProperties[] getTankProperties() {
        return this.properties;
    }

    @Override
    public int fill(FluidStack resource, boolean doFill) {
        if (doFill) {
            this.markDirty();
            IBlockState stat = this.world.getBlockState(this.pos);
            this.world.notifyBlockUpdate(this.pos, stat, stat, 3);
        }
        return this.waterTank.fill(resource, doFill);
    }

    @Override
    public FluidStack drain(FluidStack resource, boolean doDrain) {
        if (doDrain) {
            this.markDirty();
            IBlockState stat = this.world.getBlockState(this.pos);
            this.world.notifyBlockUpdate(this.pos, stat, stat, 3);
        }
        return this.waterTank.drain(resource, doDrain);
    }

    @Override
    public FluidStack drain(int maxDrain, boolean doDrain) {
        if (doDrain) {
            this.markDirty();
            IBlockState stat = this.world.getBlockState(this.pos);
            this.world.notifyBlockUpdate(this.pos, stat, stat, 3);
        }
        return this.waterTank.drain(maxDrain, doDrain);
    }

    @Override
    public boolean hasCapability(Capability<?> capability, EnumFacing facing) {
        return capability == CapabilityFluidHandler.FLUID_HANDLER_CAPABILITY || super.hasCapability(capability, facing);
    }

    @SuppressWarnings("unchecked")
    @Override
    public <T> T getCapability(Capability<T> capability, EnumFacing facing) {
        if (capability == CapabilityFluidHandler.FLUID_HANDLER_CAPABILITY)
            return (T) this;
        return super.getCapability(capability, facing);
    }
}

package thebetweenlands.common.world.storage;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Random;
import java.util.Set;

import javax.annotation.Nullable;

import gnu.trove.map.TObjectLongMap;
import gnu.trove.map.hash.TObjectLongHashMap;
import net.minecraft.block.material.Material;
import net.minecraft.block.state.IBlockState;
import net.minecraft.client.Minecraft;
import net.minecraft.entity.player.EntityPlayer;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.nbt.NBTTagList;
import net.minecraft.util.ResourceLocation;
import net.minecraft.util.SoundCategory;
import net.minecraft.util.math.BlockPos;
import net.minecraft.util.math.ChunkPos;
import net.minecraft.util.math.MathHelper;
import net.minecraft.world.EnumSkyBlock;
import net.minecraft.world.World;
import net.minecraft.world.biome.Biome;
import net.minecraft.world.chunk.Chunk;
import net.minecraftforge.common.util.Constants;
import net.minecraftforge.fml.relauncher.Side;
import net.minecraftforge.fml.relauncher.SideOnly;
import thebetweenlands.api.entity.spawning.IBiomeSpawnEntriesData;
import thebetweenlands.api.entity.spawning.ICustomSpawnEntriesProvider;
import thebetweenlands.api.entity.spawning.ICustomSpawnEntry;
import thebetweenlands.api.environment.IEnvironmentEvent;
import thebetweenlands.api.storage.IWorldStorage;
import thebetweenlands.common.config.BetweenlandsConfig;
import thebetweenlands.common.herblore.aspect.AspectManager;
import thebetweenlands.common.registries.BiomeRegistry;
import thebetweenlands.common.registries.SoundRegistry;
import thebetweenlands.common.world.biome.BiomeBetweenlands;
import thebetweenlands.common.world.event.BLEnvironmentEventRegistry;

public class BetweenlandsWorldStorage extends WorldStorageImpl {
	private BLEnvironmentEventRegistry environmentEventRegistry;
	private AspectManager aspectManager = new AspectManager();

	private Map<ICustomSpawnEntriesProvider, BiomeSpawnEntriesData> biomeSpawnEntriesData = new HashMap<>();

	protected final Set<ChunkPos> previousCheckedAmbientChunks = new HashSet<>();
	protected int ambienceTicks;
	protected int updateLCG = (new Random()).nextInt();

	protected List<SpiritTreeKillToken> spiritTreeKillTokens = new ArrayList<>();

	public BLEnvironmentEventRegistry getEnvironmentEventRegistry() {
		return this.environmentEventRegistry;
	}

	public AspectManager getAspectManager() {
		return this.aspectManager;
	}

	@Override
	public BiomeSpawnEntriesData getBiomeSpawnEntriesData(Biome biome) {
		if(biome instanceof ICustomSpawnEntriesProvider) {
			ICustomSpawnEntriesProvider provider = (ICustomSpawnEntriesProvider) biome;
			BiomeSpawnEntriesData data = this.biomeSpawnEntriesData.get(provider);
			if(data == null) {
				this.biomeSpawnEntriesData.put(provider, data = new BiomeSpawnEntriesData(provider));
			}
			return data;
		}
		return null;
	}

	@Override
	protected void init() {
		this.environmentEventRegistry = new BLEnvironmentEventRegistry(this.getWorld());
		this.environmentEventRegistry.init();

		if(!this.getWorld().isRemote) {
			for(IEnvironmentEvent event : this.environmentEventRegistry.getEvents().values()) {
				event.setDefaults();
				event.setLoaded();
			}
			this.aspectManager.loadAndPopulateStaticAspects(null, AspectManager.getAspectsSeed(this.getWorld().getWorldInfo().getSeed()));
		}

		this.ambienceTicks = this.getWorld().rand.nextInt(7000);
	}

	@Override
	public void readFromNBT(NBTTagCompound nbt) {
		if(!this.getWorld().isRemote) {
			for(IEnvironmentEvent event : this.environmentEventRegistry.getEvents().values()) {
				event.readFromNBT(nbt);
			}
			this.environmentEventRegistry.setDisabled(nbt.getBoolean("eventsDisabled"));
			this.aspectManager.loadAndPopulateStaticAspects(nbt.getCompoundTag("itemAspects"), AspectManager.getAspectsSeed(this.getWorld().getWorldInfo().getSeed()));

			this.biomeSpawnEntriesData.clear();
			if(nbt.hasKey("biomeData", Constants.NBT.TAG_COMPOUND)) {
				NBTTagCompound biomesNbt = nbt.getCompoundTag("biomeData");
				for(String key : biomesNbt.getKeySet()) {
					Biome biome = Biome.REGISTRY.getObject(new ResourceLocation(key));
					if(biome instanceof ICustomSpawnEntriesProvider) {
						this.getBiomeSpawnEntriesData(biome).readFromNbt(biomesNbt.getCompoundTag(key));
					}
				}
			}

			this.spiritTreeKillTokens.clear();
			NBTTagList spiritTreeKillTokensNbt = nbt.getTagList("spiritTreeKillTokens", Constants.NBT.TAG_COMPOUND);
			for(int i = 0; i < spiritTreeKillTokensNbt.tagCount(); i++) {
				this.spiritTreeKillTokens.add(SpiritTreeKillToken.readFromNBT(spiritTreeKillTokensNbt.getCompoundTagAt(i)));
			}
		}
	}

	@Override
	public void writeToNBT(NBTTagCompound nbt) {
		if(!this.getWorld().isRemote) {
			for(IEnvironmentEvent event : this.environmentEventRegistry.getEvents().values()) {
				event.writeToNBT(nbt);
			}
			nbt.setBoolean("eventsDisabled", this.environmentEventRegistry.isDisabled());
			NBTTagCompound aspectData = new NBTTagCompound();
			this.aspectManager.saveStaticAspects(aspectData);
			nbt.setTag("itemAspects", aspectData);

			NBTTagCompound biomesNbt = new NBTTagCompound();
			for(BiomeBetweenlands biome : BiomeRegistry.REGISTERED_BIOMES) {
				NBTTagCompound biomeSpawnEntriesNbt = new NBTTagCompound();
				this.getBiomeSpawnEntriesData(biome).writeToNbt(biomeSpawnEntriesNbt);
				biomesNbt.setTag(biome.getRegistryName().toString(), biomeSpawnEntriesNbt);
			}
			nbt.setTag("biomeData", biomesNbt);

			NBTTagList spiritTreeKillTokensNbt = new NBTTagList();
			for(SpiritTreeKillToken token : this.spiritTreeKillTokens) {
				spiritTreeKillTokensNbt.appendTag(token.writeToNBT());
			}
			nbt.setTag("spiritTreeKillTokens", spiritTreeKillTokensNbt);
		}
	}

	@Override
	public void tick() {
		super.tick();

		if(this.getWorld().isRemote && this.getWorld().provider.getDimension() == BetweenlandsConfig.WORLD_AND_DIMENSION.dimensionId) {
			this.updateAmbientCaveSounds();
		}
	}

	@SideOnly(Side.CLIENT)
	protected void updateAmbientCaveSounds() {
		Minecraft mc = Minecraft.getMinecraft();
		EntityPlayer player = mc.player;

		if(player != null) {
			Set<ChunkPos> closeChunks = new HashSet<>();

			int cx = MathHelper.floor(player.posX / 16.0D);
			int cz = MathHelper.floor(player.posZ / 16.0D);

			int chunkRadius = 3;

			for(int ox = -chunkRadius; ox <= chunkRadius; ++ox) {
				for(int oz = -chunkRadius; oz <= chunkRadius; ++oz) {
					closeChunks.add(new ChunkPos(ox + cx, oz + cz));
				}
			}

			if(this.ambienceTicks > 0) {
				--this.ambienceTicks;
			} else {
				this.previousCheckedAmbientChunks.retainAll(closeChunks);

				if(this.previousCheckedAmbientChunks.size() >= closeChunks.size()) {
					this.previousCheckedAmbientChunks.clear();
				}

				int checkedChunks = 0;

				for(ChunkPos chunkpos : closeChunks) {
					if(!this.previousCheckedAmbientChunks.contains(chunkpos)) {
						int bx = chunkpos.x * 16;
						int bz = chunkpos.z * 16;

						Chunk chunk = this.getWorld().getChunk(chunkpos.x, chunkpos.z);

						if(this.playAmbientCaveSounds(player, bx, bz, chunk)) {
							break;
						}

						this.previousCheckedAmbientChunks.add(chunkpos);
						++checkedChunks;

						if (checkedChunks >= 6) {
							break;
						}
					}
				}
			}
		}
	}

	@SideOnly(Side.CLIENT)
	protected boolean playAmbientCaveSounds(EntityPlayer player, int x, int z, Chunk chunk) {
		World world = this.getWorld();

		this.updateLCG = this.updateLCG * 3 + 1013904223;
		int rnd = this.updateLCG >> 2;
		int xo = rnd & 15;
		int zo = rnd >> 8 & 15;
		int y = rnd >> 16 & 255;
		BlockPos pos = new BlockPos(xo + x, y, zo + z);
		IBlockState state = chunk.getBlockState(pos);

		if(state.getMaterial() == Material.AIR && world.getLight(pos) <= world.rand.nextInt(8) && world.getLightFor(EnumSkyBlock.SKY, pos) <= 0) {
			double dst = player.getDistanceSq((double)pos.getX() + 0.5D, (double)pos.getY() + 0.5D, (double)pos.getZ() + 0.5D);

			if(dst > 4.0D && dst < 256.0D) {
				world.playSound((double)pos.getX() + 0.5D, (double)pos.getY() + 0.5D, (double)pos.getZ() + 0.5D, SoundRegistry.AMBIENT_CAVE_SPOOK, SoundCategory.AMBIENT, 0.85F, 0.8F + world.rand.nextFloat() * 0.2F, false);
				this.ambienceTicks = world.rand.nextInt(7000) + 3000;
				return true;
			}
		}
		return false;
	}

	public static BetweenlandsWorldStorage forWorld(World world) {
		BetweenlandsWorldStorage storage = forWorldNullable(world);
		if(storage == null) {
			throw new RuntimeException(String.format("World %s (%s) does not have BetweenlandsWorldStorage capability", world.getWorldInfo().getWorldName(), world.provider.getClass().getName()));
		}
		return storage;
	}

	@Nullable
	public static BetweenlandsWorldStorage forWorldNullable(World world) {
		IWorldStorage storage = world.getCapability(CAPABILITY_INSTANCE, null);
		if(storage instanceof BetweenlandsWorldStorage) {
			return (BetweenlandsWorldStorage) storage;
		}
		return null;
	}

	public List<SpiritTreeKillToken> getSpiritTreeKillTokens() {
		return this.spiritTreeKillTokens;
	}

	public static class BiomeSpawnEntriesData implements IBiomeSpawnEntriesData {
		public final ICustomSpawnEntriesProvider biome;

		private final TObjectLongMap<ResourceLocation> lastSpawnMap = new TObjectLongHashMap<>();

		protected BiomeSpawnEntriesData(ICustomSpawnEntriesProvider biome) {
			this.biome = biome;
		}

		@Override
		public long getLastSpawn(ICustomSpawnEntry spawnEntry) {
			return this.lastSpawnMap.containsKey(spawnEntry.getID()) ? this.lastSpawnMap.get(spawnEntry.getID()) : -1;
		}

		@Override
		public void setLastSpawn(ICustomSpawnEntry spawnEntry, long lastSpawn) {
			this.lastSpawnMap.put(spawnEntry.getID(), lastSpawn);
		}

		@Override
		public long removeLastSpawn(ICustomSpawnEntry spawnEntry) {
			return this.lastSpawnMap.remove(spawnEntry.getID());
		}

		public void readFromNbt(NBTTagCompound nbt) {
			this.lastSpawnMap.clear();
			for(ICustomSpawnEntry spawnEntry : this.biome.getCustomSpawnEntries()) {
				if(spawnEntry.isSaved()) {
					if(nbt.hasKey(spawnEntry.getID().toString(), Constants.NBT.TAG_LONG)) {
						this.lastSpawnMap.put(spawnEntry.getID(), nbt.getLong(spawnEntry.getID().toString()));
					}
				}
			}
		}

		public void writeToNbt(NBTTagCompound nbt) {
			for(ICustomSpawnEntry spawnEntry : this.biome.getCustomSpawnEntries()) {
				if(spawnEntry.isSaved()) {
					if(this.lastSpawnMap.containsKey(spawnEntry.getID())) {
						nbt.setLong(spawnEntry.getID().toString(), this.lastSpawnMap.get(spawnEntry.getID()));
					}
				}
			}
		}
	}
}

package thebetweenlands.common.world.storage;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.Callable;

import javax.annotation.Nullable;

import net.minecraft.entity.player.EntityPlayerMP;
import net.minecraft.nbt.NBTBase;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.util.EnumFacing;
import net.minecraft.util.ITickable;
import net.minecraft.util.ResourceLocation;
import net.minecraft.util.math.ChunkPos;
import net.minecraft.world.World;
import net.minecraft.world.chunk.Chunk;
import net.minecraftforge.common.MinecraftForge;
import net.minecraftforge.common.capabilities.Capability;
import net.minecraftforge.common.capabilities.Capability.IStorage;
import net.minecraftforge.common.capabilities.CapabilityInject;
import net.minecraftforge.common.capabilities.CapabilityManager;
import net.minecraftforge.common.capabilities.ICapabilitySerializable;
import net.minecraftforge.event.AttachCapabilitiesEvent;
import net.minecraftforge.fml.common.eventhandler.SubscribeEvent;
import thebetweenlands.api.storage.ILocalStorageHandler;
import thebetweenlands.api.storage.IWorldStorage;
import thebetweenlands.common.TheBetweenlands;
import thebetweenlands.common.config.BetweenlandsConfig;
import thebetweenlands.common.lib.ModInfo;

public abstract class WorldStorageImpl implements IWorldStorage {
	////////////// Handler //////////////////
	public static class Handler {
		private Handler() {}

		@SubscribeEvent
		public static void onWorldCapability(final AttachCapabilitiesEvent<World> event) {
			event.addCapability(new ResourceLocation(ModInfo.ID, "world_data"), new ICapabilitySerializable<NBTTagCompound>() {
				private IWorldStorage instance = this.getNewInstance();

				private IWorldStorage getNewInstance() {
					WorldStorageImpl instance = new BetweenlandsWorldStorage();
					instance.setWorld(event.getObject());
					instance.init();
					return instance;
				}

				@Override
				public boolean hasCapability(Capability<?> capability, EnumFacing facing) {
					return capability == CAPABILITY_INSTANCE;
				}

				@SuppressWarnings("unchecked")
				@Override
				public <T> T getCapability(Capability<T> capability, EnumFacing facing) {
					return capability == CAPABILITY_INSTANCE ? (T)this.instance : null;
				}

				@Override
				public NBTTagCompound serializeNBT() {
					return (NBTTagCompound) CAPABILITY_INSTANCE.getStorage().writeNBT(CAPABILITY_INSTANCE, this.instance, null);
				}

				@Override
				public void deserializeNBT(NBTTagCompound nbt) {
					CAPABILITY_INSTANCE.getStorage().readNBT(CAPABILITY_INSTANCE, this.instance, null, nbt);					
				}
			});
		}
	}

	/**
	 * Returns the world capability for the specified world
	 * @param world
	 * @return
	 */
	@Nullable
	public static IWorldStorage getCapability(World world) {
		return world.getCapability(CAPABILITY_INSTANCE, null);
	}

	/**
	 * Called after the world is set
	 */
	protected void init() {

	}

	/**
	 * Registers the capability and event handler
	 */
	public static void register() {
		CapabilityManager.INSTANCE.register(IWorldStorage.class, new IStorage<IWorldStorage>() {
			@Override
			public NBTBase writeNBT(Capability<IWorldStorage> capability, IWorldStorage instance, EnumFacing side) {
				NBTTagCompound nbt = new NBTTagCompound();
				instance.writeToNBT(nbt);
				return nbt;
			}

			@Override
			public void readNBT(Capability<IWorldStorage> capability, IWorldStorage instance, EnumFacing side, NBTBase nbt) {
				if(nbt instanceof NBTTagCompound) {
					instance.readFromNBT((NBTTagCompound)nbt);
				}
			}
		}, new Callable<IWorldStorage>() {
			@Override
			public IWorldStorage call() throws Exception {
				return new BetweenlandsWorldStorage();
			}
		});

		MinecraftForge.EVENT_BUS.register(Handler.class);
	}
	////////////// End Handler //////////////////





	@CapabilityInject(IWorldStorage.class)
	public static final Capability<IWorldStorage> CAPABILITY_INSTANCE = null;

	private Map<ChunkPos, ChunkStorageImpl> storageMap = new HashMap<>();
	private List<ITickable> tickableStorages = new ArrayList<>();

	private World world;

	private ILocalStorageHandler localStorageHandler;

	/**
	 * Sets the capability's world
	 * @param world
	 */
	private void setWorld(World world) {
		this.world = world;
		this.localStorageHandler = new LocalStorageHandlerImpl(this);
	}

	@Override
	public World getWorld() {
		return this.world;
	}

	@Override
	public void writeToNBT(NBTTagCompound nbt) {

	}

	@Override
	public void readFromNBT(NBTTagCompound nbt) {

	}

	@Override
	public void loadChunk(Chunk chunk) {
		if(!this.storageMap.containsKey(chunk.getPos())) {
			try {
				ChunkStorageImpl storage = new BetweenlandsChunkStorage(this, chunk);
				storage.init();
				storage.setDefaults();
				this.storageMap.put(chunk.getPos(), storage);

				if(storage instanceof ITickable) {
					this.tickableStorages.add((ITickable) storage);
				}

				//Makes sure that the default values are saved
				chunk.setModified(true);
			} catch(Exception ex) {
				TheBetweenlands.logger.error(String.format("Failed creating chunk storage at %s", "[x=" + chunk.x + ", z=" + chunk.z + "]"), ex);
			}
		}
	}

	@Override
	public void readAndLoadChunk(Chunk chunk, NBTTagCompound nbt) {
		if(this.storageMap.containsKey(chunk.getPos())) {
			if(BetweenlandsConfig.DEBUG.debug) TheBetweenlands.logger.warn(String.format("Reading chunk storage at %s, but chunk storage is already loaded!", "[x=" + chunk.x + ", z=" + chunk.z + "]"));
		} else {
			try {
				ChunkStorageImpl storage = new BetweenlandsChunkStorage(this, chunk);
				storage.init();
				storage.readFromNBT(nbt, false);
				this.storageMap.put(chunk.getPos(), storage);

				if(storage instanceof ITickable) {
					this.tickableStorages.add((ITickable) storage);
				}
			} catch(Exception ex) {
				TheBetweenlands.logger.error(String.format("Failed reading chunk storage at %s", "[x=" + chunk.x + ", z=" + chunk.z + "]"), ex);
			}
		}
	}

	@Override
	public void unloadChunk(Chunk chunk) {
		if(!this.storageMap.containsKey(chunk.getPos())) {
			if(BetweenlandsConfig.DEBUG.debug) TheBetweenlands.logger.warn(String.format("Unloading chunk storage at %s, but chunk storage is not loaded!", "[x=" + chunk.x + ", z=" + chunk.z + "]"));
		} else {
			ChunkStorageImpl storage = this.storageMap.remove(chunk.getPos());
			if(storage instanceof ITickable) {
				this.tickableStorages.remove((ITickable) storage);
			}
			storage.onUnload();
		}
	}

	@Override
	public NBTTagCompound saveChunk(Chunk chunk) {
		if(!this.storageMap.containsKey(chunk.getPos())) {
			if(BetweenlandsConfig.DEBUG.debug) TheBetweenlands.logger.warn(String.format("Saving chunk storage at %s, but chunk storage is not loaded!", "[x=" + chunk.x + ", z=" + chunk.z + "]"));
		} else {
			try {
				ChunkStorageImpl storage = this.storageMap.get(chunk.getPos());
				NBTTagCompound nbt = storage.writeToNBT(new NBTTagCompound(), false);
				storage.setDirty(false);
				return nbt;
			} catch(Exception ex) {
				TheBetweenlands.logger.error(String.format("Failed saving chunk storage at %s", "[x=" + chunk.x + ", z=" + chunk.z + "]"), ex);
			}
		}
		return null;
	}

	@Override
	public void watchChunk(ChunkPos pos, EntityPlayerMP player) {
		ChunkStorageImpl storage = this.storageMap.get(pos);
		if(storage != null) {
			storage.addWatcher(player);
		}
	}

	@Override
	public void unwatchChunk(ChunkPos pos, EntityPlayerMP player) {
		ChunkStorageImpl storage = this.storageMap.get(pos);
		if(storage != null) {
			storage.removeWatcher(player);
		}
	}

	@Override
	public ChunkStorageImpl getChunkStorage(Chunk chunk) {
		return this.storageMap.get(chunk.getPos());
	}

	@Override
	public ILocalStorageHandler getLocalStorageHandler() {
		return this.localStorageHandler;
	}

	@Override
	public void tick() {
		this.localStorageHandler.update();

		for(int i = 0; i < this.tickableStorages.size(); i++) {
			ITickable tickable = this.tickableStorages.get(i);
			tickable.update();
		}
	}
}
